import React, { useEffect, useState } from 'react';
import {
    Box,
    ThemeProvider,
    Container,
    Grid,
    Alert,
    AlertTitle,
    CssBaseline,
    Fade,
    Tabs,
    Tab,
    Paper,
} from '@mui/material';
import axios from 'axios';
import theme from './theme';
import Header from './components/layout/Header';
import MetricCard from './components/common/MetricCard';
import StatusBadge from './components/common/StatusBadge';
import LoadingScreen from './components/common/LoadingScreen';
import ForecastChart from './components/dashboard/ForecastChart';
import AlertPanel from './components/dashboard/AlertPanel';
import DataTable from './components/dashboard/DataTable';
import ModelMetrics from './components/dashboard/ModelMetrics';
import { DashboardData, ChartDataPoint } from './types';
import { formatNumber, formatPercentage, getTimeAgo } from './utils/formatters';

// Icons
import InventoryIcon from '@mui/icons-material/Inventory';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import AssessmentIcon from '@mui/icons-material/Assessment';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';

// API Base URL from environment
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8000/api/v1';

function App() {
    const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [lastUpdated, setLastUpdated] = useState<string>('');
    const [currentTab, setCurrentTab] = useState(0);

    const fetchData = async () => {
        try {
            setLoading(true);
            setError(null);

            const response = await axios.get(`${API_BASE_URL}/forecast/latest`);
            setDashboardData(response.data);
            setLastUpdated(new Date().toLocaleTimeString());
            setLoading(false);
        } catch (error: any) {
            console.error('Error fetching forecast data:', error);
            setError(error.message || 'Failed to fetch data');
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const interval = setInterval(fetchData, 300000); // Refresh every 5 minutes

        return () => clearInterval(interval);
    }, []);

    const formatChartData = (data: DashboardData | null): ChartDataPoint[] => {
        if (!data?.tactical_forecasts) return [];

        return data.tactical_forecasts.map((forecast) => ({
            date: forecast.timestamp,
            predicted: forecast.predicted_stockpile,
            actual: forecast.actual_stockpile,
            lower: forecast.confidence_lower,
            upper: forecast.confidence_upper,
        }));
    };

    const handleRefresh = () => {
        fetchData();
    };

    const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
        setCurrentTab(newValue);
    };

    return (
        <ThemeProvider theme={theme}>
            <CssBaseline />
            <Box sx={{ minHeight: '100vh', backgroundColor: 'background.default' }}>
                <Header
                    lastUpdated={lastUpdated}
                    onRefresh={handleRefresh}
                    loading={loading}
                />

                <Container maxWidth="xl" sx={{ py: 4 }}>
                    {loading && !dashboardData ? (
                        <LoadingScreen message="Loading dashboard data..." />
                    ) : error ? (
                        <Fade in>
                            <Alert
                                severity="error"
                                sx={{
                                    maxWidth: 600,
                                    mx: 'auto',
                                    mt: 4,
                                    borderRadius: 3,
                                }}
                            >
                                <AlertTitle sx={{ fontWeight: 700 }}>Error Loading Data</AlertTitle>
                                {error}
                            </Alert>
                        </Fade>
                    ) : (
                        <Fade in>
                            <Box>
                                {/* Navigation Tabs */}
                                <Paper
                                    sx={{
                                        mb: 3,
                                        borderRadius: 3,
                                        overflow: 'hidden',
                                    }}
                                >
                                    <Tabs
                                        value={currentTab}
                                        onChange={handleTabChange}
                                        sx={{
                                            '& .MuiTab-root': {
                                                fontWeight: 700,
                                                fontSize: '1rem',
                                                textTransform: 'none',
                                                minHeight: 56,
                                                px: 4,
                                            },
                                        }}
                                    >
                                        <Tab label="Dashboard" />
                                        <Tab label="Detailed Data" />
                                        <Tab label="Model Performance" />
                                    </Tabs>
                                </Paper>

                                {/* Tab Panel 0: Dashboard Overview */}
                                {currentTab === 0 && (
                                    <Grid container spacing={3}>
                                        {/* Top Metrics Row */}
                                        <Grid item xs={12} sm={6} md={3}>
                                            <MetricCard
                                                title="Current Stockpile"
                                                value={formatNumber(dashboardData?.summary?.current_stockpile || 0)}
                                                unit="Kt"
                                                icon={<InventoryIcon sx={{ fontSize: 32 }} />}
                                                color="primary"
                                                trend={dashboardData?.summary?.trend}
                                                change={
                                                    dashboardData?.summary?.change_percentage
                                                        ? `${dashboardData.summary.change_percentage > 0 ? '+' : ''}${formatPercentage(
                                                            dashboardData.summary.change_percentage,
                                                            1
                                                        )}`
                                                        : undefined
                                                }
                                            />
                                        </Grid>

                                        <Grid item xs={12} sm={6} md={3}>
                                            <MetricCard
                                                title="7-Day Forecast"
                                                value={formatNumber(dashboardData?.summary?.forecast_7_days || 0)}
                                                unit="Kt"
                                                icon={<CalendarTodayIcon sx={{ fontSize: 32 }} />}
                                                color="info"
                                            />
                                        </Grid>

                                        <Grid item xs={12} sm={6} md={3}>
                                            <MetricCard
                                                title="30-Day Forecast"
                                                value={formatNumber(dashboardData?.summary?.forecast_30_days || 0)}
                                                unit="Kt"
                                                icon={<TrendingUpIcon sx={{ fontSize: 32 }} />}
                                                color="success"
                                            />
                                        </Grid>

                                        <Grid item xs={12} sm={6} md={3}>
                                            <MetricCard
                                                title="Model Accuracy"
                                                value={formatPercentage(dashboardData?.summary?.model_accuracy || 0)}
                                                unit=""
                                                icon={<AssessmentIcon sx={{ fontSize: 32 }} />}
                                                color="warning"
                                            />
                                        </Grid>

                                        {/* Status and Last Updated */}
                                        <Grid item xs={12}>
                                            <Box
                                                sx={{
                                                    display: 'flex',
                                                    justifyContent: 'space-between',
                                                    alignItems: 'center',
                                                    p: 2,
                                                    backgroundColor: 'background.paper',
                                                    borderRadius: 3,
                                                    border: '1px solid',
                                                    borderColor: 'divider',
                                                }}
                                            >
                                                <Box display="flex" alignItems="center" gap={2}>
                                                    <Box sx={{ color: 'text.secondary', fontWeight: 600 }}>
                                                        System Status:
                                                    </Box>
                                                    <StatusBadge
                                                        status={dashboardData?.summary?.status || 'Unknown'}
                                                        size="medium"
                                                    />
                                                </Box>
                                                <Box sx={{ color: 'text.secondary', fontSize: '0.875rem', fontWeight: 600 }}>
                                                    Last updated: {dashboardData?.summary?.last_updated ? getTimeAgo(dashboardData.summary.last_updated) : 'Unknown'}
                                                </Box>
                                            </Box>
                                        </Grid>

                                        {/* Main Chart */}
                                        <Grid item xs={12} lg={8}>
                                            <ForecastChart
                                                data={formatChartData(dashboardData)}
                                                loading={loading && !dashboardData}
                                                showConfidenceInterval={true}
                                            />
                                        </Grid>

                                        {/* Alerts Panel */}
                                        <Grid item xs={12} lg={4}>
                                            <AlertPanel
                                                alerts={dashboardData?.alerts || []}
                                                loading={loading && !dashboardData}
                                            />
                                        </Grid>
                                    </Grid>
                                )}

                                {/* Tab Panel 1: Detailed Data */}
                                {currentTab === 1 && (
                                    <Grid container spacing={3}>
                                        <Grid item xs={12}>
                                            <DataTable
                                                data={dashboardData?.tactical_forecasts || []}
                                                loading={loading && !dashboardData}
                                                title="Tactical Forecast Data"
                                            />
                                        </Grid>
                                    </Grid>
                                )}

                                {/* Tab Panel 2: Model Performance */}
                                {currentTab === 2 && (
                                    <Grid container spacing={3}>
                                        <Grid item xs={12} md={6}>
                                            <ModelMetrics
                                                metrics={{
                                                    accuracy: dashboardData?.summary?.model_accuracy || 0,
                                                    mae: 0.05,
                                                    rmse: 0.08,
                                                    r2_score: 0.92,
                                                }}
                                                loading={loading && !dashboardData}
                                            />
                                        </Grid>
                                        <Grid item xs={12} md={6}>
                                            <ForecastChart
                                                data={formatChartData(dashboardData)}
                                                title="Prediction Accuracy Over Time"
                                                showConfidenceInterval={false}
                                            />
                                        </Grid>
                                    </Grid>
                                )}
                            </Box>
                        </Fade>
                    )}
                </Container>
            </Box>
        </ThemeProvider>
    );
}

export default App;
